import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"蒙","description":"周易集解 - 蒙","frontmatter":{"title":"蒙","description":"周易集解 - 蒙"},"headers":[],"relativePath":"classics/jijie/004.md","filePath":"classics/jijie/004.md"}'),l={name:"classics/jijie/004.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="蒙" tabindex="-1">蒙 <a class="header-anchor" href="#蒙" aria-label="Permalink to “蒙”">​</a></h1><h2 id="蒙-1" tabindex="-1">蒙 <a class="header-anchor" href="#蒙-1" aria-label="Permalink to “蒙”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>蒙，亨。匪我求童蒙，童蒙求我。初筮告，再三瀆，瀆則不告，利貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：物生必蒙，故受之以蒙。蒙者，蒙也，物之穉也。</p><p>崔憬曰：萬物始生之後，漸以長穉，故言物生必蒙。</p><p>鄭玄曰：蒙，幼小之貌。齊人謂萌為蒙也。</p><p>虞翻曰：艮三之二。亨謂二。震剛柔接，故亨。蒙亨以通，行時中也。</p><p>乾寶曰：蒙者，離宮陰也。世在四。八月之時，降陽佈德，薺麥並生，而息來在寅，故蒙。於世為八月，於消息為正月卦也。正月之時，陽氣上達，故屯為物之始生，蒙為物之穉也。施之於人，則童蒙也。苟得其運，雖蒙必亨，故曰蒙亨。此蓋以寄成王之遭周公也。</p><p>虞翻曰：童蒙謂五，艮為童蒙。我謂二也。震為動起，嫌求之五，故曰匪我求童蒙。五陰求陽，故童蒙求我，志應也。艮為求，二體師象，坎為經。謂禮有來學，無往教。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：蒙，山下有險，險而止，蒙。蒙亨，以亨行，時中也。匪我求童蒙，童蒙求我，志應也。初筮告，以剛中也。再三瀆，瀆則不告，瀆蒙也。蒙以養正，聖功也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>侯果曰：艮為山，坎為險，是山下有險。險被山止，止則未通，矇昧之象也。</p><p>荀爽曰：此本艮卦也。</p><p>案：二進居三，三降居二。剛柔得中，故能通。發蒙時，令得時中矣。故曰蒙亨，以亨行時中也。</p><p>陸績曰：六五陰爻，在蒙暗。蒙又體艮，少男，故曰童蒙。</p><p>荀爽曰：二與五志相應也。</p><p>崔憬曰：以二剛中，能發於蒙也。</p><p>荀爽曰：再三，謂三與四也。皆乘陽，不敬，故曰瀆。瀆不能尊陽，蒙氣不除，故曰瀆蒙也。</p><p>虞翻曰：體頤，故養。五多功。聖謂二，二志應五，變得正而忘其蒙，故聖功也。</p><p>乾寶曰：武王之崩，年九十三矣。而成王八歲，言天后成王之年，將以養公正之道，而成三聖之功。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：山下出泉，蒙。君子以果行育德。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：艮為山，震為出，坎泉流出，故山下出泉。</p><p>虞翻曰：君子為二。艮為果，震為行。育，養也。二至上有頤養象，故以果行育德也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，發蒙，利用刑人，用說桎梏，以往吝。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：發蒙之正，初為蒙始，而失其位。發蒙之正以成兌，兌為刑人，坤為用，故曰利用刑人矣。坎為穿木，震足艮手，互與坎連，故稱桎梏。初發成兌，兌為說，坎象毀壞，故曰用說桎梏。之應歷險，故以往吝。吝，小疵也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：利用刑人，以正法也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：坎為法，初發之正，故正法也。</p><p>乾寶曰：初六戊寅，平明之時，天光始照，故曰發蒙。此成王始覺周公至誠之象也。坎為法律，寅為貞廉，以貞用刑，故利用刑人矣。此成王將正四國之象也。說，解也。正四國之罪。宜釋周公之黨，故曰用說桎梏。既感金滕之文，追恨昭德之晚，故曰以往吝。初二失位，吝之由也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，包蒙，吉。納婦吉，子克家。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：子克家，剛柔接也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：坤為包。應五據初，一與三四同體，包養四陰，故包蒙吉。震剛為夫，伏巽為婦，二以剛接柔，故納婦吉。二稱家。震長子，主器者。納婦成初。故有子克家也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，勿用娶女，見金夫，不有躬，無攸利。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：謂三誡上也。金夫謂二。初發成兌，故三稱女。兌為見。陽稱金。震為夫。三逆乘二陽，所行不順，為二所淫。上來之三，陟陰。故曰「勿用娶女，見金夫」矣。坤身稱躬，三為二所乘，兌澤動下，不得之應，故不有躬。失位多兇，故無攸利也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：勿用娶女，行不順也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：失位乘剛，故行不順也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，困蒙，吝。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：困蒙之吝，獨遠實也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：陽稱實也。獨遠於陽，處兩陰之中，闇莫之發，故曰困蒙也。困於矇昧，不能比賢以發其志，亦鄙矣，故曰吝。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，童蒙，吉。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：艮為童蒙，處貴承上，有應於二，動而成巽，故吉也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：童蒙之吉，順以巽也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：順於上，巽於二，有似成王任用周召也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，擊蒙，不利為寇，利禦寇。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：體艮為手，故擊。謂五已變，上動成坎，稱寇。而逆乘陽，故不利為寇矣。御，止也。此寇謂二。坎為寇，巽為高，艮為山，登山備下，順有師象，故利禦寇也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：利用禦寇，上下順也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：自上御下，故順也。</p>',73)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
